AssistantMessageToolRequest(name='create', tool_call_id='tooluse_uRqJlxku1hqh2ZW780963o', arguments={'file_text': '/* Dark theme color palette */
:root {
    --bg-primary: #121212;
    --bg-secondary: #1e1e1e;
    --bg-tertiary: #2a2a2a;
    --text-primary: #e8e8e8;
    --text-secondary: #b0b0b0;
    --accent-primary: #6366f1;
    --accent-hover: #818cf8;
    --accent-active: #4f46e5;
    --border-color: #383838;
    --error-color: #ef4444;
    --success-color: #10b981;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    height: 100%;
}

body {
    background-color: var(--bg-primary);
    color: var(--text-primary);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    font-size: 16px;
    line-height: 1.5;
}

.container {
    max-width: 600px;
    margin: 0 auto;
    padding: 40px 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100%;
}

main {
    width: 100%;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 32px;
    color: var(--text-primary);
}

form {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 32px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.form-field {
    margin-bottom: 32px;
}

fieldset {
    border: none;
    padding: 0;
    margin: 0;
}

legend {
    font-size: 18px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 20px;
    display: block;
    padding: 0;
}

.radio-group {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.radio-option {
    display: flex;
    align-items: center;
    padding: 12px;
    border-radius: 8px;
    cursor: pointer;
    transition: background-color 0.2s ease, border-color 0.2s ease;
    border: 2px solid transparent;
}

.radio-option:hover {
    background-color: var(--bg-tertiary);
}

input[type="radio"] {
    appearance: none;
    -webkit-appearance: none;
    width: 20px;
    height: 20px;
    border: 2px solid var(--text-secondary);
    border-radius: 50%;
    cursor: pointer;
    background-color: var(--bg-secondary);
    margin-right: 12px;
    flex-shrink: 0;
    transition: border-color 0.2s ease, background-color 0.2s ease;
    outline: none;
}

input[type="radio"]:hover {
    border-color: var(--accent-hover);
}

input[type="radio"]:checked {
    border-color: var(--accent-primary);
    background: radial-gradient(circle, var(--accent-primary) 40%, transparent 40%),
        radial-gradient(circle, var(--accent-primary) 40%, transparent 40%);
    background-color: var(--accent-primary);
}

input[type="radio"]:focus-visible {
    outline: 2px solid var(--accent-primary);
    outline-offset: 2px;
}

input[type="radio"]:disabled {
    cursor: not-allowed;
    opacity: 0.5;
    background-color: var(--bg-tertiary);
    border-color: var(--border-color);
}

label {
    cursor: pointer;
    font-size: 16px;
    color: var(--text-primary);
    user-select: none;
}

.submit-btn {
    background-color: var(--accent-primary);
    color: white;
    border: none;
    padding: 12px 28px;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.2s ease, transform 0.1s ease;
    outline: none;
}

.submit-btn:hover:not(:disabled) {
    background-color: var(--accent-hover);
}

.submit-btn:active:not(:disabled) {
    background-color: var(--accent-active);
    transform: scale(0.98);
}

.submit-btn:focus-visible {
    outline: 2px solid var(--accent-primary);
    outline-offset: 2px;
}

.submit-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Ensure adequate contrast and readability */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
    .radio-option {
        border: 2px solid var(--text-secondary);
    }

    input[type="radio"] {
        border-width: 3px;
    }
}

/* Reflow support for narrow viewports */
@media (max-width: 480px) {
    .container {
        padding: 20px 16px;
    }

    form {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
        margin-bottom: 24px;
    }

    legend {
        font-size: 16px;
        margin-bottom: 16px;
    }

    .radio-group {
        gap: 12px;
    }

    .radio-option {
        padding: 10px;
    }

    label {
        font-size: 15px;
    }
}
