    const form = document.getElementById('preferencesForm');
    const radioInputs = document.querySelectorAll('input[name="notification-method"]');

    form.addEventListener('submit', function(event) {
        event.preventDefault();

        const selectedValue = Array.from(radioInputs).find(radio => radio.checked)?.value;

        if (!selectedValue) {
            radioInputs[0].focus();
            return;
        }

        console.log('Notification preference saved:', selectedValue);
        alert(`Your notification preference has been saved: ${selectedValue.charAt(0).toUpperCase() + selectedValue.slice(1)}`);
    });

    radioInputs.forEach(radio => {
        radio.addEventListener('change', function() {
            console.log('Selection changed to:', this.value);
        });
    });
});
